void Solver::rephase() {
    rephases = 0;
    threshold *= 0.85;
    rephase_limit += 10240;

    // Update saved phases based on current trail state
    int update_count = 0;
    for (int i = 1; i <= vars && update_count < 1000; i++) {
        if (value[i] != 0) {  // Variable is assigned
            saved[i] = value[i];
            update_count++;
        }
    }
}
